  1	using System.Runtime.CompilerServices;
  2	using System.Windows;
  3	using System.Windows.Automation;
  4	using System.Windows.Controls;
  5	using DesktopPet.Core.I18n;
  6	
  7	namespace DesktopPet.App.Localization;
  8	
  9	/// <summary>
 10	/// Tracks static WPF strings on first discovery, then refreshes only those tracked slots.
 11	/// Dynamic user/model content created later is never discovered during a language refresh.
 12	/// </summary>
 13	public static class WpfLocalizer
 14	{
 15	    public sealed record LocalizedArgument(string Key);
 16	
 17	    private sealed class Entry
 18	    {
 19	        public string? Title;
 20	        public string? Text;
 21	        public object?[]? TextArguments;
 22	        public string? Content;
 23	        public object?[]? ContentArguments;
 24	        public string? Header;
 25	        public string? ToolTip;
 26	        public object?[]? ToolTipArguments;
 27	        public string? AutomationName;
 28	        public object?[]? AutomationArguments;
 29	    }
 30	
 31	    private static readonly ConditionalWeakTable<DependencyObject, Entry> Entries = new();
 32	
 33	    public static void ApplyNew(DependencyObject root, I18nService i18n)
 34	        => Apply(root, i18n, discover: true, new HashSet<DependencyObject>());
 35	
 36	    public static void RefreshTracked(DependencyObject root, I18nService i18n)
 37	        => Apply(root, i18n, discover: false, new HashSet<DependencyObject>());
 38	
 39	    public static LocalizedArgument Localize(string key) => new(key);
 40	
 41	    public static void SetText(TextBlock block, string key, I18nService i18n)
 42	    {
 43	        var entry = Entries.GetOrCreateValue(block);
 44	        entry.Text = key;
 45	        entry.TextArguments = null;
 46	        block.Text = i18n.T(key);
 47	    }
 48	
 49	    public static void SetFormattedText(
 50	        TextBlock block,
 51	        string template,
 52	        I18nService i18n,
 53	        params object?[] args)
 54	    {
 55	        var entry = Entries.GetOrCreateValue(block);
 56	        entry.Text = template;
 57	        entry.TextArguments = args.ToArray();
 58	        block.Text = i18n.Format(template, ResolveArguments(i18n, args));
 59	    }
 60	
 61	    public static void SetFormattedContent(
 62	        ContentControl control,
 63	        string template,
 64	        I18nService i18n,
 65	        params object?[] args)
 66	    {
 67	        var entry = Entries.GetOrCreateValue(control);
 68	        entry.Content = template;
 69	        entry.ContentArguments = args.ToArray();
 70	        control.Content = i18n.Format(template, ResolveArguments(i18n, args));
 71	    }
 72	
 73	    public static void SetFormattedToolTip(
 74	        FrameworkElement element,
 75	        string template,
 76	        I18nService i18n,
 77	        params object?[] args)
 78	    {
 79	        var entry = Entries.GetOrCreateValue(element);
 80	        entry.ToolTip = template;
 81	        entry.ToolTipArguments = args.ToArray();
 82	        element.ToolTip = i18n.Format(template, ResolveArguments(i18n, args));
 83	    }
 84	
 85	    public static void SetFormattedAutomationName(
 86	        DependencyObject element,
 87	        string template,
 88	        I18nService i18n,
 89	        params object?[] args)
 90	    {
 91	        var entry = Entries.GetOrCreateValue(element);
 92	        entry.AutomationName = template;
 93	        entry.AutomationArguments = args.ToArray();
 94	        AutomationProperties.SetName(element, i18n.Format(template, ResolveArguments(i18n, args)));
 95	    }
 96	
 97	    private static void Apply(
 98	        DependencyObject current,
 99	        I18nService i18n,
100	        bool discover,
101	        HashSet<DependencyObject> visited)
102	    {
103	        if (!visited.Add(current)) return;
104	        if (discover) Discover(current);
105	        if (Entries.TryGetValue(current, out var entry)) Translate(current, entry, i18n);
106	
107	        foreach (var child in LogicalTreeHelper.GetChildren(current))
108	        {
109	            if (child is DependencyObject dependency)
110	                Apply(dependency, i18n, discover, visited);
111	        }
112	    }
113	
114	    private static void Discover(DependencyObject current)
115	    {
116	        Entry? entry = null;
117	        if (current is Window window && IsCatalogText(window.Title))
118	            (entry ??= Entries.GetOrCreateValue(current)).Title = window.Title;
119	        if (current is TextBlock textBlock && IsCatalogText(textBlock.Text))
120	            (entry ??= Entries.GetOrCreateValue(current)).Text = textBlock.Text;
121	        if (current is ContentControl contentControl
122	            && contentControl.Content is string content
123	            && IsCatalogText(content))
124	        {
125	            (entry ??= Entries.GetOrCreateValue(current)).Content = content;
126	        }
127	        if (current is HeaderedItemsControl headered
128	            && headered.Header is string header
129	            && IsCatalogText(header))
130	        {
131	            (entry ??= Entries.GetOrCreateValue(current)).Header = header;
132	        }
133	        if (current is FrameworkElement automationElement
134	            && AutomationProperties.GetName(automationElement) is { Length: > 0 } automationName
135	            && IsCatalogText(automationName))
136	        {
137	            (entry ??= Entries.GetOrCreateValue(current)).AutomationName = automationName;
138	        }
139	        if (current is FrameworkElement element
140	            && element.ToolTip is string toolTip
141	            && IsCatalogText(toolTip))
142	        {
143	            (entry ??= Entries.GetOrCreateValue(current)).ToolTip = toolTip;
144	        }
145	    }
146	
147	    private static void Translate(DependencyObject current, Entry entry, I18nService i18n)
148	    {
149	        if (current is Window window && entry.Title is not null)
150	            window.Title = i18n.T(entry.Title);
151	        if (current is TextBlock textBlock && entry.Text is not null)
152	            textBlock.Text = entry.TextArguments is { } textArgs
153	                ? i18n.Format(entry.Text, ResolveArguments(i18n, textArgs))
154	                : i18n.T(entry.Text);
155	        if (current is ContentControl contentControl && entry.Content is not null)
156	            contentControl.Content = entry.ContentArguments is { } contentArgs
157	                ? i18n.Format(entry.Content, ResolveArguments(i18n, contentArgs))
158	                : i18n.T(entry.Content);
159	        if (current is HeaderedItemsControl headered && entry.Header is not null)
160	            headered.Header = i18n.T(entry.Header);
161	        if (current is FrameworkElement element && entry.ToolTip is not null)
162	            element.ToolTip = entry.ToolTipArguments is { } toolTipArgs
163	                ? i18n.Format(entry.ToolTip, ResolveArguments(i18n, toolTipArgs))
164	                : i18n.T(entry.ToolTip);
165	        if (current is DependencyObject automationElement && entry.AutomationName is not null)
166	            AutomationProperties.SetName(
167	                automationElement,
168	                entry.AutomationArguments is { } automationArgs
169	                    ? i18n.Format(entry.AutomationName, ResolveArguments(i18n, automationArgs))
170	                    : i18n.T(entry.AutomationName));
171	    }
172	
173	    private static object?[] ResolveArguments(I18nService i18n, object?[] args)
174	        => args.Select(argument => argument is LocalizedArgument localized
175	            ? i18n.T(localized.Key)
176	            : argument).ToArray();
177	
178	    private static bool IsCatalogText(string? text)
179	        => !string.IsNullOrWhiteSpace(text)
180	           && I18nService.HasTranslation(AppLang.En, text);
181	}
