 27	public partial class App : Application
 28	{
 29	    private const string InstanceMutexName = @"Global\DesktopPet.Native.SingleInstance";
 30	    private Mutex? _instanceMutex;
 31	    private bool _ownsMutex;
 32	    private PetWindowManager? _manager;
 33	    private TrayController? _tray;
 34	    private FileJsonStore? _store;
 35	    private AiCoordinator? _ai;
 36	    private ModeService? _modeService;
 37	    private ChatWindow? _chatWindow;
 38	    private HotkeyManager? _hotkeys;
 39	    private HotkeySettingsCoordinator? _hotkeyCoordinator;
 40	    private LanguageCoordinator? _languageCoordinator;
 41	    private DesktopPet.Core.I18n.I18nService? _i18n;
 42	    private RollingFileLogger? _logger;
 43	    private FullscreenSuppressionMonitor? _fullscreenMonitor;
 44	    private HwndSource? _hotkeySource;
 45	    private Window? _hotkeyHost;
 46	    private bool _startupInProgress;
 47	    private bool _startupWelcomePending;
 48	
 49	    public App()
 50	    {
 51	        DispatcherUnhandledException += HandleDispatcherException;
 52	    }
 53	
 54	    private void HandleDispatcherException(
 55	        object? sender,
 56	        System.Windows.Threading.DispatcherUnhandledExceptionEventArgs e)
 57	    {
 58	        if (e.Exception is not JsonStoreException storageError) return;
 59	        PersistenceErrorPresenter.Report(storageError);
 60	        e.Handled = true;
 61	        if (_startupInProgress || _startupWelcomePending) Shutdown(-1);
 62	    }
 63	
 64	    protected override void OnStartup(StartupEventArgs e)
 65	    {
 66	        _startupInProgress = true;
 67	        base.OnStartup(e);
 68	        WaitForParentRestart(e.Args);
 69	
 70	        // 单实例（对齐 Tauri 版 tauri_plugin_single_instance：第二实例直接退出，
 71	        // Phase 4 接设置窗跳转）
 72	        _instanceMutex = new Mutex(initiallyOwned: true, InstanceMutexName, out var createdNew);
 73	        _ownsMutex = createdNew;
 74	        if (!createdNew)
 75	        {
 76	            _startupInProgress = false;
 77	            Shutdown();
 78	            return;
 79	        }
 80	
 81	        var isBench = e.Args.Any(a => a.StartsWith("--bench-"));
 82	        if (isBench) PetWindow.BenchLogEnabled = true;
 83	
 84	        var paths = AppDataPaths.ForCurrentUser();
 85	        var dataDir = paths.Root;
 86	        _logger = new RollingFileLogger(paths.Logs, "app");
 87	        _logger.Info("App", "startup");
 88	        _store = new FileJsonStore(dataDir);
 89	
 90	        var store = isBench ? PetStoreModel.EmptyPetStore() : InitializeStore();
 91	        _manager = new PetWindowManager(
 92	            _store,
 93	            new SpriteLoader(dataDir, logger: _logger),
 94	            _logger);
 95	        _manager.SetDiagnosticExporter(new DiagnosticExporter(paths.Logs, () => _logger?.Flush()));
 96	        _manager.SetFactoryResetHandler(ExecuteFactoryResetAsync);
 97	        _manager.Reconcile(store, _store.LoadGlobalVisibility());
 98	
 99	        if (!isBench)
100	        {
101	            // 语言优先读已保存设置（设置页语言页）；首次启动才用系统检测
102	            var storedSettings = _store.LoadSettings();
103	            var i18n = new DesktopPet.Core.I18n.I18nService(
104	                storedSettings?.Lang ?? DesktopPet.Core.I18n.I18nService.Detect());
105	            _i18n = i18n;
106	            PersistenceErrorPresenter.Configure(i18n);
107	            _manager.SetI18n(i18n);
108	            var settings = AppSettings.Normalize(storedSettings ?? AppSettings.Defaults(i18n.Lang));
109	            _manager.ApplySettings(settings);
110	            _manager.CreateFloatingBall(dataDir);
111	            _tray = new TrayController(_manager, i18n);
112	
113	            // Phase 5：AI 编排（总开关/Agent 进程/输出模式/对话/记账）
114	            var chatWindow = new ChatWindow(i18n);
115	            _chatWindow = chatWindow;
116	            chatWindow.IsVisibleChanged += (_, _) =>
117	                _manager?.SetChatVisible(chatWindow.IsVisible && chatWindow.WindowState != WindowState.Minimized);
118	            chatWindow.StateChanged += (_, _) =>
119	                _manager?.SetChatVisible(chatWindow.IsVisible && chatWindow.WindowState != WindowState.Minimized);
120	            _manager.SettingsForegroundChanged += settingsForeground =>
121	                chatWindow.Topmost = !settingsForeground;
122	            var fullscreenDetector = new FullscreenWindowDetector();
123	            _modeService = new ModeService(
124	                danmakuFactory: () => new DanmakuWindow(
125	                    SystemParameters.VirtualScreenWidth,
126	                    SystemParameters.VirtualScreenHeight,
127	                    i18n: i18n),
128	                routeToChat: output =>
129	                {
130	                    ShowChatWindow();
131	                    _chatWindow?.AppendAssistantAsync(output.Text);
132	                },
133	                routeToBubble: text => _manager.BroadcastQuickBubble(text),
134	                isFullscreen: fullscreenDetector.IsSuppressed);
135	            _fullscreenMonitor = new FullscreenSuppressionMonitor(
136	                fullscreenDetector.IsSuppressed,
137	                suppressed => _modeService?.SetFullscreenSuppressed(suppressed),
138	                TimeSpan.FromMilliseconds(250));
139	            _fullscreenMonitor.Start();
140	            MigrateProviderCredentials();
141	            _ai = new AiCoordinator(
142	                _store,
143	                _modeService,
144	                _chatWindow,
145	                RecordTokens,
146	                ResolveAgentHostPath(),
147	                i18n,
148	                _logger);
149	            _chatWindow.SendRequested += async (text, ctx) =>
150	            {
151	                if (_ai is not null) await _ai.SendChatAsync(text, ctx);
152	            };
153	            _chatWindow.PersonaSwitchRequested += _ =>
154	            {
155	                // 对话窗顶部人格名点击 → 打开设置 AI 页（人格卡片主入口）
156	                _manager.OpenSettings();
157	                _manager.NavigateSettingsToAi();
158	            };
159	            _chatWindow.RestartRequested += () => _ai?.ClearChatHistory(); // 重开 = 清 L1 会话窗口
160	            _manager.SetAiCoordinator(_ai);
161	            _manager.SetOutputModeHandler(ApplyOutputModeFromBall);
162	            _manager.SetOpenChatHandler(ShowChatWindow);
163	            _languageCoordinator = new LanguageCoordinator(
164	                _store,
165	                i18n,
166	                PublishLanguage,
167	                settings.Lang);
168	            _manager.SetLanguageChangeHandler(_languageCoordinator.ChangeLanguageAsync);
169	            _ai.ApplySettings(settings); // 应用已保存 AI 设置（默认关 = 不起 Agent）
170	            _chatWindow.TtsEnabled = settings.Ai.TtsEnabled; // 朗读按钮初始状态（AI 助手页开关）
171	            RegisterGlobalHotkeys(settings.Hotkeys);
172	            if (_hotkeys is not null)
173	            {
174	                _hotkeyCoordinator = new HotkeySettingsCoordinator(
175	                    _store,
176	                    _hotkeys,
177	                    settings.Lang,
178	                    i18n);
179	                _manager.SetHotkeySettingsHandler(ApplyHotkeySettings);
180	            }
181	
182	            // 初始化引导：AI 已开启但未设置称呼/人格 → 弹引导窗（之后设置页可改）
183	            if (settings.Ai.Enabled && !settings.Ai.Onboarded)
184	            {
185	                ShowWelcomeOnboarding();
186	            }
187	
188	            if (e.Args.Contains("--settings"))
189	            {
190	                _manager.OpenSettings();
191	            }
192	
193	            if (e.Args.Contains("--chat"))
194	            {
195	                ShowChatWindow();
196	            }
197	        }
198	
199	        var benchIndex = Array.FindIndex(e.Args, a => a.StartsWith("--bench-"));
200	        if (benchIndex >= 0)
201	        {
202	            var arg = e.Args[benchIndex];
203	            var ms = 8000;
204	            var eq = arg.IndexOf('=');
205	            if (eq > 0 && int.TryParse(arg[(eq + 1)..], out var parsed)) ms = parsed;
206	            if (arg.StartsWith("--bench-drag")) BenchMode.RunDrag(_manager, ms);
207	            else if (arg.StartsWith("--bench-idle")) BenchMode.RunIdle(_manager, ms);
208	        }
209	        _startupInProgress = false;
210	    }
