212	    /// <summary>
213	    /// 加载/初始化宠物 store。Phase 3：tauri-export.json（Tauri localStorage 导出）
214	    /// 存在时一次性迁移（实例 + 养成状态），完成后删除导出文件。
215	    /// </summary>
216	    private PetStore InitializeStore()
217	    {
218	        var store = _store!.LoadPetStore();
219	        var exportPath = Path.Combine(
220	            Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),
221	            "DesktopPet", "tauri-export.json");
222	        string? exportJson;
223	        try
224	        {
225	            exportJson = File.ReadAllText(exportPath);
226	        }
227	        catch (Exception ex) when (ex is FileNotFoundException or DirectoryNotFoundException)
228	        {
229	            exportJson = null;
230	        }
231	        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
232	        {
233	            throw new JsonStoreException("读取迁移文件", exportPath, ex);
234	        }
235	
236	        // 导出文件本身是迁移提交标记：任一目标保存失败时保留，下一次启动幂等重放。
237	        if (exportJson is not null)
238	        {
239	            try
240	            {
241	                using var doc = System.Text.Json.JsonDocument.Parse(exportJson);
242	                var result = TauriMigration.Migrate(doc.RootElement, DateTime.Now);
243	                if (result.HadData)
244	                {
245	                    _store.SavePetStore(result.Store);
246	                    _store.SaveCare(result.Care);
247	                    store = result.Store;
248	                }
249	                DeleteMigrationMarker(exportPath);
250	                System.Diagnostics.Debug.WriteLine($"Tauri migration imported {result.Store.Instances.Count} pet(s), {result.Care.Count} care state(s)");
251	            }
252	            catch (JsonStoreException)
253	            {
254	                throw;
255	            }
256	            catch (JsonException ex)
257	            {
258	                // 导出格式损坏时保留文件，避免误删用户可人工恢复的数据。
259	                System.Diagnostics.Debug.WriteLine("Tauri migration JSON invalid: " + ex.Message);
260	            }

