 11	/// <summary>Single language transition path: persist first, then publish UI state.</summary>
 12	public sealed class LanguageCoordinator
 13	{
 14	    private readonly Func<AppSettings?> _load;
 15	    private readonly Action<AppSettings> _save;
 16	    private readonly I18nService _i18n;
 17	    private readonly Action<AppSettings> _publish;
 18	    private readonly AppLang _fallback;
 19	    private readonly SemaphoreSlim _gate = new(1, 1);
 20	
 21	    public LanguageCoordinator(
 22	        IJsonStore store,
 23	        I18nService i18n,
 24	        Action<AppSettings> publish,
 25	        AppLang fallback)
 26	        : this(store.LoadSettings, store.SaveSettings, i18n, publish, fallback)
 27	    {
 28	    }
 29	
 30	    public LanguageCoordinator(
 31	        Func<AppSettings?> load,
 32	        Action<AppSettings> save,
 33	        I18nService i18n,
 34	        Action<AppSettings> publish,
 35	        AppLang fallback)
 36	    {
 37	        _load = load;
 38	        _save = save;
 39	        _i18n = i18n;
 40	        _publish = publish;
 41	        _fallback = fallback;
 42	    }
 43	
 44	    public async Task<LanguageChangeResult> ChangeLanguageAsync(
 45	        AppLang language,
 46	        CancellationToken ct = default)
 47	    {
 48	        await _gate.WaitAsync(ct);
 49	        try
 50	        {
 51	            var current = await Task.Run(
 52	                () => AppSettings.Normalize(_load() ?? AppSettings.Defaults(_fallback)),
 53	                ct);
 54	            var next = current with { Lang = language };
 55	            try
 56	            {
 57	                await Task.Run(() => _save(next), ct);
 58	            }
 59	            catch (JsonStoreException ex)
 60	            {
 61	                return new LanguageChangeResult(false, current, ex);
 62	            }
 63	
 64	            _i18n.SetLang(language);
 65	            _publish(next);
 66	            return new LanguageChangeResult(true, next);
 67	        }
 68	        finally
 69	        {
 70	            _gate.Release();
 71	        }
 72	    }
 73	}
