   396	    private void RenderBubble()
   397	    {
   398	        var now = _roamClock.NowMs();
   399	        var quickText = _quickBubble.Current();
   400	        if (quickText is not null)
   401	        {
   402	            _renderSignature = null;
   403	            _bubble.RenderLine(quickText);
   404	            SnugBubble();
   405	            return;
   406	        }
   407	
   408	        // Phase 2 无 activity 生产者：resolved 恒 idle；celebrate 供 Phase 3 升级触发
   409	        const string resolved = "idle";
   410	        var celebrating = now < _celebrateUntil;
   411	        var mood = celebrating ? "celebrate" : resolved;
   412	        if (celebrating)
   413	        {
   414	            // 庆祝行绑定（无绑定/越界 → 默认 celebrate 行）
   415	            var bound = PetAnimationResolver.ResolveBind(
   416	                _instance.Actions, PetActionTriggers.Celebrate, _renderer?.ClipCount ?? 0);
   417	            _renderer?.SetState(mood, bound);
   418	        }
   419	        else
   420	        {
   421	            _renderer?.SetState(mood);
   422	        }
   423	        // 闲谈台词节奏：庆祝结束过渡 / 首次 / 每 _idleChatterIntervalMs 换一句
   424	        //（PickMoodLine 内部遵守"显示闲谈"开关）
   425	        if (celebrating && _wasCelebrating && now >= _celebrateUntil)
   426	        {
   427	            PickMoodLine(resolved);
   428	            _moodLinePickedAtMs = now;
   429	        }
   430	        else if (!celebrating && (_moodLine is null || now - _moodLinePickedAtMs > _idleChatterIntervalMs))
   431	        {
   432	            PickMoodLine(resolved);
   433	            _moodLinePickedAtMs = now;
   434	        }
   435	        _wasCelebrating = celebrating;
   436	
   437	        var signature = $"{mood}|{_moodLine}|{(celebrating ? _celebrateText : "")}";
   438	        if (signature != _renderSignature)
   439	        {
   440	            _renderSignature = signature;
   441	            if (celebrating)
   442	            {
   443	                _bubble.RenderLine(_celebrateText.Length > 0 ? _celebrateText : _i18n.T("Done!"));
   444	            }
   445	            else if (_moodLine is { Length: > 0 })
   446	            {
   447	                _bubble.RenderLine(_moodLine);
   448	            }
   449	            else
   450	            {
   451	                _bubble.Hide();
   452	            }
   453	        }
   454	        SnugBubble();
   455	    }
