   509	        private sealed class OneShot(Action callback, long delayMs) : IDisposable
   510	        {
   511	            private readonly DispatcherTimer _timer = new()
   512	            {
   513	                Interval = TimeSpan.FromMilliseconds(Math.Max(0, delayMs)),
