   549	    /// <summary>异步加载真实精灵（本地缓存/CDN），完成后切渲染器；失败保持占位。</summary>
   550	    private async void LoadSpriteAsync()
   551	    {
   552	        if (_spriteLoading) return;
   553	        _spriteLoading = true;
   554	        try
   555	        {
   556	            var sheet = await Task.Run(() => _spriteLoader.LoadAsync(_instance.SpriteSlug));
   557	            if (sheet is not null && _hwnd != 0 && IsVisible)
   558	            {
   559	                // 待机动作轮播：由实例动作配置解析（未配置 = 全行随机 5s；关闭 = null）
   560	                var idle = PetAnimationResolver.ResolveIdle(_instance.Actions, sheet.Clips.Count);
   561	                _renderer = new PetRenderer(sheet, idle);
   562	                _lastIdleSwitchMs = _roamClock.NowMs();
   563	                ApplyPendingRenderSettings(); // 尺寸/浮动/播放列表设置（可能先于精灵加载到达）
   564	                _renderer.SetState("idle");
   565	                _animationTimer.Interval = TimeSpan.FromMilliseconds(1000.0 / _renderer.Fps);
   566	                DrawFrame(0);
   567	                RestartAnimation();
   568	                SpriteLoaded?.Invoke(); // 浮球球体刷新（启动时序：浮球创建早于精灵缓存就绪）
   569	            }
   570	        }
   571	        catch (Exception)
   572	        {
   573	            // 加载失败保持占位精灵，不影响窗口
   574	        }
   575	        finally
   576	        {
