   614	    /// <summary>
   615	    /// 消息级拖拽（绕过 WPF 事件系统——WPF 会合并丢弃捕获后的 WM_MOUSEMOVE，
   616	    /// 且事件分发有额外开销）。语义对齐 windows/src/window-drag.ts：
   617	    /// alpha hitTest 命中才按下；4px 阈值区分点击/拖拽；直接 SetWindowPos。
   618	    /// </summary>
   619	    private void OnRawLeftDown(nint lParam)
   620	    {
   621	        if (_dragState.IsDragging || _dragState.IsPressed) return;
   622	        var client = ClientPointOfMessage(lParam);
   623	        if (!HitTestSprite(client)) return;
   624	
   625	        _dragState.Begin();
   626	        _pressPoint = client;
   627	        _pressTickMs = Environment.TickCount64;
   628	        var cursor = NativeMethods.CursorPosition();
   629	        var windowPos = PhysicalPosition();
   630	        _grabOffset = (cursor.X - windowPos.X, cursor.Y - windowPos.Y);
   631	        CaptureMouse();
   632	        _roamEngine.BeginManualDrag(); // 采样起点 + 取消抛掷（对齐 beginManualDrag）
   633	        BenchTrace($"raw down hit at {client.X},{client.Y}");
   634	    }
   635	
   636	    private void OnRawMove(nint lParam)
   637	    {
   638	        if (!_dragState.IsPressed) return;
   639	        var client = ClientPointOfMessage(lParam);
   640	        var crossedThreshold = !_dragState.IsDragging && MovedBeyondThreshold(client);
   641	        if (crossedThreshold)
   642	        {
   643	            _dragState.StartDragging();
   644	            ApplyDragRow(true); // 拖拽动作行（最高优先级，无绑定则保持当前动作）
   645	            BenchTrace("raw drag started");
   646	        }
   647	        if (!_dragState.IsDragging) return;
   648	
   649	        var cursor = NativeMethods.CursorPosition();
   650	        var targetX = cursor.X - _grabOffset.X;
   651	        var targetY = cursor.Y - _grabOffset.Y;
   652	        var messageTime = NativeMethods.MessageTime();
   653	        var sw = Stopwatch.StartNew();
   654	        _roamEngine.MoveManualDrag(new RoamPoint(targetX, targetY)); // 移动 + 物理采样
   655	        sw.Stop();
   656	        _processingLatencyMs.Add(sw.Elapsed.TotalMilliseconds);
   657	        // 端到端：消息生成 → 窗口位移完成（含系统输入管线/队列等待）
   658	        _endToEndLatencyMs.Add(Math.Max(0, Environment.TickCount64 - messageTime));
   659	    }
   660	
   661	    private void OnRawLeftUp()
   662	    {
   663	        if (!_dragState.IsPressed) return;
   664	        var terminalAction = _dragState.Complete();
   665	        ReleaseMouseCapture();
   666	
   667	        if (terminalAction == DragTerminalAction.CommitPosition)
   668	        {
   669	            ApplyDragRow(false);
   670	            _roamEngine.FinishManualDrag();
   671	            var (x, y) = PhysicalPosition();
   672	            _onDragFinished(this, x, y);
   673	            BenchTrace($"raw drag finished at {x},{y}");
   674	        }
   675	        else if (terminalAction == DragTerminalAction.Click
   676	                 && Environment.TickCount64 - _pressTickMs <= 280)
   677	        {
   678	            // 未超阈值 = 点击（对齐 WindowDragController clickMaxMs + onClick）
   679	            OnPetClick();
   680	        }
   681	    }
