   683	    private void CancelPointerInteraction()
   684	    {
   685	        if (!_dragState.IsPressed && !_dragState.IsDragging) return;
   686	        var wasDragging = _dragState.IsDragging;
   687	        _dragState.Cancel();
   688	        if (IsMouseCaptured) ReleaseMouseCapture();
   689	        if (wasDragging) ApplyDragRow(false);
   690	        _roamEngine.CancelManualDrag();
   691	        BenchTrace("raw pointer interaction cancelled");
   692	    }
