   738	    /// <summary>WM 消息 lParam 的客户区坐标（物理像素，低 16 位 x，高 16 位 y）。</summary>
   739	    private static (int X, int Y) ClientPointOfMessage(nint lParam)
   740	    {
   741	        var raw = lParam.ToInt64();
