   795	            var target = TimeSpan.FromMilliseconds(1000.0 / fps);
   796	            if (Math.Abs(_animationTimer.Interval.TotalMilliseconds - target.TotalMilliseconds) > 1)
   797	            {
   798	                _animationTimer.Interval = target; // 帧率随状态行变化（fps 3-8）
   799	            }
   800	        }
   801	        else
   802	        {
   803	            _frameIndex++;
   804	            DrawFrame(_frameIndex % PlaceholderPet.Frames.Count);
