   808	    /// <summary>精灵中心物理坐标（bench 拖拽按下点；buffer 即物理像素）。</summary>
   809	    public (int X, int Y) SpriteCenterPhysical
   810	    {
   811	        get
   812	        {
   813	            if (_renderer is not null)
   814	            {
   815	                var (x, y, w, h) = _renderer.SpriteRect;
   816	                return (x + w / 2, y + h / 2);
