   818	            var (scale, dx, dy) = SpritePlacement();
   819	            var (pw, ph) = (PlaceholderPet.FrameWidth * scale, PlaceholderPet.FrameHeight * scale);
   820	            return (dx + pw / 2, dy + ph / 2);
   821	        }
