   824	    private (int Scale, int Dx, int Dy) SpritePlacement()
   825	    {
   826	        var scale = Math.Max(1, Math.Min(
   827	            _bufferWidth / PlaceholderPet.FrameWidth,
   828	            _bufferHeight / PlaceholderPet.FrameHeight));
   829	        return (scale, (_bufferWidth - PlaceholderPet.FrameWidth * scale) / 2, _bufferHeight - PlaceholderPet.FrameHeight * scale);
   830	    }
