   861	    /// <summary>把当前精灵帧绘制到帧缓冲（renderer）或占位精灵（回退）。</summary>
   862	    private void DrawFrame(int frameIndex)
   863	    {
   864	        if (_renderer is not null && TryPresentCachedSpriteFrame()) return;
   865	
   866	        RestoreWriteableBitmapPresentation();
   867	        var buffer = _frameBuffer.Clear();
   868	        if (_renderer is not null)
   869	        {
   870	            _renderer.DrawFrame(buffer, _bufferWidth, _bufferHeight);
   871	            ApplyStageOverlay(buffer);
   872	        }
   873	        else
   874	        {
   875	            DrawPlaceholderFrame(buffer, frameIndex);
   876	        }
   877	        PixelBuffer.RgbaToBgra(buffer); // Core 输出 RGBA，WriteableBitmap 是 Bgra32（防 R/B 错位）
   878	        _bitmap.WritePixels(
   879	            new Int32Rect(0, 0, _bufferWidth, _bufferHeight),
   880	            buffer, _bufferWidth * 4, 0);
   881	    }
   882	
   883	    private void DrawPlaceholderFrame(byte[] buffer, int frameIndex)
   884	    {
   885	        var frame = PlaceholderPet.Frames[frameIndex % PlaceholderPet.Frames.Count];
   886	        var (scale, dx, dy) = SpritePlacement();
   887	
   888	        for (var fy = 0; fy < PlaceholderPet.FrameHeight; fy++)
   889	        {
   890	            for (var fx = 0; fx < PlaceholderPet.FrameWidth; fx++)
   891	            {
   892	                var src = (fy * PlaceholderPet.FrameWidth + fx) * 4;
   893	                if (frame.Rgba[src + 3] == 0) continue;
   894	                for (var sy = 0; sy < scale; sy++)
   895	                {
   896	                    var y = dy + fy * scale + sy;
   897	                    for (var sx = 0; sx < scale; sx++)
   898	                    {
   899	                        var dst = ((y * _bufferWidth) + dx + fx * scale + sx) * 4;
   900	                        buffer[dst] = frame.Rgba[src];
   901	                        buffer[dst + 1] = frame.Rgba[src + 1];
   902	                        buffer[dst + 2] = frame.Rgba[src + 2];
   903	                        buffer[dst + 3] = frame.Rgba[src + 3];
   904	                    }
   905	                }
