   581	    private nint WndProcHook(nint hwnd, int msg, nint wParam, nint lParam, ref bool handled)
   582	    {
   583	        const int wmMouseMove = 0x0200;
   584	        const int wmLeftDown = 0x0201;
   585	        const int wmLeftUp = 0x0202;
   586	        const int wmCancelMode = 0x001F;
   587	        const int wmCaptureChanged = 0x0215;
   588	        const nint mkLeftButton = 0x0001;
   589	        switch (msg)
   590	        {
   591	            case wmLeftDown:
   592	                BenchTrace($"raw msg down client={ClientPointOfMessage(lParam)} cursor={NativeMethods.CursorPosition()}");
   593	                OnRawLeftDown(lParam);
   594	                handled = true;
   595	                break;
   596	            case wmMouseMove when _dragState.IsPressed && (wParam.ToInt64() & mkLeftButton) != 0:
   597	                OnRawMove(lParam);
   598	                handled = true;
   599	                break;
   600	            case wmLeftUp:
   601	                BenchTrace($"raw msg up pressed={_dragState.IsPressed}");
   602	                if (_dragState.IsPressed) OnRawLeftUp();
   603	                handled = true;
   604	                break;
