   661	    private void OnRawLeftUp()
   662	    {
   663	        if (!_dragState.IsPressed) return;
   664	        var terminalAction = _dragState.Complete();
   665	        ReleaseMouseCapture();
   666	
   667	        if (terminalAction == DragTerminalAction.CommitPosition)
   668	        {
   669	            ApplyDragRow(false);
   670	            _roamEngine.FinishManualDrag();
   671	            var (x, y) = PhysicalPosition();
   672	            _onDragFinished(this, x, y);
   673	            BenchTrace($"raw drag finished at {x},{y}");
   674	        }
   675	        else if (terminalAction == DragTerminalAction.Click
   676	                 && Environment.TickCount64 - _pressTickMs <= 280)
   677	        {
   678	            // 未超阈值 = 点击（对齐 WindowDragController clickMaxMs + onClick）
   679	            OnPetClick();
   680	        }
   681	    }
