     1	using DesktopPet.Core.Hotkeys;
     2	using DesktopPet.Core.I18n;
     3	using DesktopPet.Core.Storage;
     4	using DesktopPet.Infra.Hotkey;
     5	
     6	namespace DesktopPet.App.Hotkeys;
     7	
     8	public sealed record HotkeySettingsUpdateResult(
     9	    bool Success,
    10	    AppSettings? Settings,
    11	    string Message,
    12	    bool RollbackComplete,
    13	    HotkeyApplyResult RuntimeResult,
    14	    JsonStoreException? PersistenceError = null);
    15	
    16	/// <summary>
    17	/// Coordinates the runtime replacement and JSON commit as one compensating transaction.
    18	/// It reloads settings at commit time so an open settings window cannot overwrite newer fields.
    19	/// </summary>
    20	public sealed class HotkeySettingsCoordinator
    21	{
    22	    private readonly Func<AppSettings?> _load;
    23	    private readonly Action<AppSettings> _save;
    24	    private readonly IHotkeyRuntime _runtime;
    25	    private readonly AppLang _fallbackLanguage;
    26	    private readonly I18nService? _i18n;
    27	
    28	    public HotkeySettingsCoordinator(
    29	        IJsonStore store,
    30	        IHotkeyRuntime runtime,
    31	        AppLang fallbackLanguage,
    32	        I18nService? i18n = null)
    33	        : this(store.LoadSettings, store.SaveSettings, runtime, fallbackLanguage, i18n)
    34	    {
    35	    }
    36	
    37	    public HotkeySettingsCoordinator(
    38	        Func<AppSettings?> load,
    39	        Action<AppSettings> save,
    40	        IHotkeyRuntime runtime,
    41	        AppLang fallbackLanguage,
    42	        I18nService? i18n = null)
    43	    {
    44	        _load = load;
    45	        _save = save;
    46	        _runtime = runtime;
    47	        _fallbackLanguage = fallbackLanguage;
    48	        _i18n = i18n;
    49	    }
    50	
    51	    public HotkeySettingsUpdateResult Apply(HotkeySettings candidate)
    52	    {
    53	        ArgumentNullException.ThrowIfNull(candidate);
    54	        var current = AppSettings.Normalize(_load() ?? AppSettings.Defaults(_fallbackLanguage));
    55	        var runtimeResult = _runtime.TryReplaceAll(candidate);
    56	        if (!runtimeResult.Success)
    57	        {
    58	            return new HotkeySettingsUpdateResult(
    59	                false,
    60	                current,
    61	                DescribeRuntimeFailure(runtimeResult, _i18n),
    62	                runtimeResult.RollbackComplete,
    63	                runtimeResult);
    64	        }
    65	
    66	        var next = current with { Hotkeys = candidate };
    67	        try
    68	        {
    69	            _save(next);
    70	            return new HotkeySettingsUpdateResult(
    71	                true, next, Translate("快捷键已应用"), true, runtimeResult);
    72	        }
    73	        catch (JsonStoreException persistenceError)
    74	        {
    75	            var rollback = _runtime.TryReplaceAll(current.Hotkeys);
    76	            var rollbackComplete = rollback.Success;
    77	            var message = rollbackComplete
    78	                ? Translate("设置保存失败，运行时快捷键已恢复")
    79	                : Translate("设置保存失败，运行时快捷键未能完整恢复");
    80	            return new HotkeySettingsUpdateResult(
    81	                false,
    82	                current,
    83	                message,
    84	                rollbackComplete,
    85	                rollback,
    86	                persistenceError);
    87	        }
    88	    }
    89	
    90	    private string Translate(string key) => _i18n?.T(key) ?? key;
    91	
    92	    public static string DescribeRuntimeFailure(HotkeyApplyResult result, I18nService? i18n = null)
    93	    {
    94	        string Translate(string key) => i18n?.T(key) ?? key;
    95	        if (result.Phase == "validation")
    96	        {
    97	            if (result.ValidationIssues.Any(issue => issue.Code == "duplicate"))
    98	                return Translate("快捷键重复，请为每个动作设置不同组合");
    99	            return Translate("快捷键组合无效，主键必须搭配 Ctrl、Alt、Shift 或 Win");
   100	        }
   101	
   102	        var action = result.FailedAction switch
   103	        {
   104	            HotkeyAction.TogglePets => Translate("显示或隐藏宠物"),
   105	            HotkeyAction.ToggleMode => Translate("切换输出模式"),
   106	            HotkeyAction.OpenSettings => Translate("打开设置"),
   107	            HotkeyAction.Quit => Translate("退出应用"),
   108	            _ => Translate("快捷键"),
   109	        };
   110	        var reason = result.NativeError == 1409
   111	            ? Translate("已被其他程序占用")
   112	            : i18n?.Format("系统错误 {0}", result.NativeError) ?? $"系统错误 {result.NativeError}";
   113	        var rollback = result.RollbackComplete
   114	            ? Translate("旧快捷键保持不变")
   115	            : Translate("旧快捷键未能完整恢复");
   116	        return i18n?.Format("{0}注册失败：{1}；{2}", action, reason, rollback)
   117	               ?? $"{action}注册失败：{reason}；{rollback}";
   118	    }
   119	}
