1637	    private static HotkeyModifiers ReadHotkeyModifiers()
1638	    {
1639	        var current = Keyboard.Modifiers;
1640	        var modifiers = HotkeyModifiers.None;
1641	        if ((current & ModifierKeys.Control) != 0) modifiers |= HotkeyModifiers.Control;
1642	        if ((current & ModifierKeys.Alt) != 0) modifiers |= HotkeyModifiers.Alt;
1643	        if ((current & ModifierKeys.Shift) != 0) modifiers |= HotkeyModifiers.Shift;
1644	        if ((current & ModifierKeys.Windows) != 0) modifiers |= HotkeyModifiers.Windows;
1645	        return modifiers;
1646	    }
