1648	    private static bool IsModifierKey(Key key)
1649	        => key is Key.LeftCtrl or Key.RightCtrl or Key.LeftAlt or Key.RightAlt
1650	            or Key.LeftShift or Key.RightShift or Key.LWin or Key.RWin;
1651	
1652	    private static string FormatHotkey(HotkeyGesture? gesture)
1653	    {
1654	        if (gesture is null) return "未绑定";
1655	        var parts = new List<string>();
1656	        if ((gesture.Modifiers & HotkeyModifiers.Control) != 0) parts.Add("Ctrl");
1657	        if ((gesture.Modifiers & HotkeyModifiers.Alt) != 0) parts.Add("Alt");
1658	        if ((gesture.Modifiers & HotkeyModifiers.Shift) != 0) parts.Add("Shift");
1659	        if ((gesture.Modifiers & HotkeyModifiers.Windows) != 0) parts.Add("Win");
1660	        parts.Add(KeyInterop.KeyFromVirtualKey((int)gesture.VirtualKey).ToString());
1661	        return string.Join(" + ", parts);
1662	    }
