1667	    {
1668	        var stack = new StackPanel();
1669	        var lang = new WrapPanel { Margin = new Thickness(0, 2, 0, 0) };
1670	        foreach (var (value, label) in new[]
1671	        {
1672	            (AppLang.En, "English"), (AppLang.ZhHans, "简体中文"),
1673	            (AppLang.ZhHant, "繁體中文"), (AppLang.Vi, "Tiếng Việt"),
1674	        })
1675	        {
1676	            var radio = new RadioButton { Content = label, IsChecked = _settings.Lang == value, Margin = new Thickness(0, 0, 20, 0) };
1677	            radio.Checked += async (_, _) =>
1678	            {
1679	                if (_settings.Lang == value) return;
1680	                if (_changeLanguage is null)
1681	                {
1682	                    Save(settings => settings with { Lang = value });
1683	                    if (_settings.Lang == value)
1684	                    {
1685	                        _i18n.SetLang(value);
1686	                        ApplyLocalization();
1687	                    }
1688	                    return;
1689	                }
1690	                var result = await _changeLanguage(value, CancellationToken.None);
1691	                if (result.PersistenceError is not null)
1692	                {
1693	                    PersistenceErrorPresenter.Report(result.PersistenceError, this);
1694	                    ShowPage("language");
1695	                    return;
1696	                }
1697	                if (result.Settings is not null) _settings = result.Settings;
1698	            };
1699	            lang.Children.Add(radio);
1700	        }
1701	        stack.Children.Add(SectionCard("语言 / Language", lang, margin: 0));
1702	
