1610	                    && editors.TryGetValue(conflicting, out var conflictingEditor))
1611	                    conflictingEditor.BorderBrush = Brush("DangerBrush");
1612	            }
1613	            if (result.Success && result.Settings is not null)
1614	                _settings = result.Settings;
1615	        };
1616	
1617	        bindings.Children.Add(apply);
1618	        bindings.Children.Add(status);
1619	        var stack = new StackPanel();
1620	        stack.Children.Add(SectionCard("全局快捷键", bindings, margin: 0));
1621	        return PageScroller(stack, PageHeader("快捷键", "全局操作绑定"));
