1624	    private static HotkeySettings SetHotkey(
1625	        HotkeySettings settings,
1626	        HotkeyAction action,
1627	        HotkeyGesture? gesture)
1628	        => action switch
1629	        {
1630	            HotkeyAction.TogglePets => settings with { TogglePets = gesture },
1631	            HotkeyAction.ToggleMode => settings with { ToggleMode = gesture },
1632	            HotkeyAction.OpenSettings => settings with { OpenSettings = gesture },
1633	            HotkeyAction.Quit => settings with { Quit = gesture },
1634	            _ => settings,
1635	        };
