  6	namespace DesktopPet.App;
  7	
  8	/// <summary>统一把持久化故障呈现给用户；存储层仍负责抛出，不在 UI 层静默吞掉。</summary>
  9	internal static class PersistenceErrorPresenter
 10	{
 11	    private static int _dialogOpen;
 12	    private static I18nService _i18n = new();
 13	
 14	    public static void Configure(I18nService i18n) => _i18n = i18n;
 15	
 16	    public static void Report(JsonStoreException exception, Window? owner = null)
 17	    {
 18	        Debug.WriteLine($"JSON persistence failed ({exception.Operation}): {exception.FilePath}: {exception.InnerException?.Message}");
 19	        var app = Application.Current;
 20	        if (app is null)
 21	        {
 22	            return;
 23	        }
 24	
 25	        void Show()
 26	        {
 27	            if (Interlocked.Exchange(ref _dialogOpen, 1) != 0) return;
 28	            try
 29	            {
 30	                var i18n = _i18n;
 31	                MessageBox.Show(
 32	                    owner,
 33	                    i18n.Format(
 34	                        "无法{0}桌宠数据。请检查数据目录权限或磁盘空间。\n\n{1}",
 35	                        i18n.T(exception.Operation),
 36	                        exception.FilePath),
 37	                    "DesktopPet",
 38	                    MessageBoxButton.OK,
 39	                    MessageBoxImage.Error);
 40	            }
 41	            finally
 42	            {
 43	                Volatile.Write(ref _dialogOpen, 0);
 44	            }
 45	        }
 46	
 47	        if (app.Dispatcher.CheckAccess())
 48	        {
 49	            Show();
 50	        }
 51	        else
 52	        {
 53	            _ = app.Dispatcher.BeginInvoke(Show);
 54	        }
 55	    }
 56	}
