 15	/// </summary>
 16	public sealed class SpritePreviewWindow : Window
 17	{
 18	    private readonly SpriteSheet _sheet;
 19	    private readonly byte[] _sourceBytes;
 20	    private readonly string _suggestedName;
 21	
 22	    public SpritePreviewWindow(
 23	        SpriteSheet sheet,
 24	        byte[] sourceBytes,
 25	        string suggestedName,
 26	        I18nService? i18n = null)
 27	    {
 28	        var localization = i18n ?? new I18nService();
 29	        _sheet = sheet;
 30	        _sourceBytes = sourceBytes;
 31	        _suggestedName = suggestedName;
 32	
 33	        Title = "切片预览 — DesktopPet";
 34	        Width = 620;
 35	        Height = 480;
 36	        WindowStartupLocation = WindowStartupLocation.CenterOwner;
 37	        ResizeMode = ResizeMode.NoResize;
 38	        Background = (Brush)Application.Current.FindResource("WindowBgBrush");
 39	
 40	        var root = new StackPanel { Margin = new Thickness(16) };
 41	
 42	        var header = new TextBlock
 43	        {
 44	            Text = localization.Format("{0} — 检测到 {1} 行动画", suggestedName, sheet.Clips.Count),
 45	            FontSize = 14,
 46	            FontWeight = FontWeights.SemiBold,
 47	            Margin = new Thickness(0, 0, 0, 10),
 48	        };
 49	        root.Children.Add(header);
 50	
 51	        // 原图 + 网格线覆盖。修复：曾误用压缩文件字节（_sourceBytes）当像素缓冲，
 52	        // 缓冲不足抛异常（async void 调用链无 handler → 进程崩溃）或显示垃圾像素；
 53	        // 现在用 Decode 保留的解码 RGBA 构建（Core 输出 RGBA，WPF 需 BGRA）。
 54	        var imageArea = new Grid { Width = 384, Height = 320, HorizontalAlignment = HorizontalAlignment.Center };
 55	        var source = BuildSourcePreview(sheet);
 56	        var image = new Image { Source = source, Stretch = Stretch.Uniform, Width = 384, Height = 320 };
 57	        imageArea.Children.Add(image);
 58	
 59	        var overlay = new Canvas { Width = 384, Height = 320 };
 60	        var scaleX = 384.0 / sheet.SourceWidth;
 61	        var scaleY = 320.0 / sheet.SourceHeight;
 62	        foreach (var clip in sheet.Clips)
 63	        {
 64	            foreach (var frame in clip)
 65	            {
 66	                var rect = new System.Windows.Shapes.Rectangle
 67	                {
 68	                    Width = frame.Width * scaleX,
 69	                    Height = frame.Height * scaleY,
 70	                    Stroke = new SolidColorBrush(Color.FromRgb(0xFF, 0x8A, 0x65)),
 71	                    StrokeThickness = 1,
 72	                    StrokeDashArray = [3, 2],
 73	                };
 74	                Canvas.SetLeft(rect, frame.RectX * scaleX);
 75	                Canvas.SetTop(rect, frame.RectY * scaleY);
 76	                overlay.Children.Add(rect);
 77	            }
 78	        }
 79	        imageArea.Children.Add(overlay);
 80	        root.Children.Add(imageArea);
 81	
 82	        // 帧条：每行首帧缩略图
 83	        var frameStrip = new WrapPanel { Margin = new Thickness(0, 12, 0, 0), MaxWidth = 600 };
 84	        foreach (var clip in _sheet.Clips)
 85	        {
 86	            if (clip.Count == 0) continue;
 87	            var frame = clip[0];
 88	            var thumb = new Image
 89	            {
 90	                Source = FrameToBitmap(frame),
 91	                Width = 56,
 92	                Height = 56 * frame.Height / (double)frame.Width,
 93	                Stretch = Stretch.Uniform,
 94	                Margin = new Thickness(2),
 95	                SnapsToDevicePixels = true,
 96	            };
 97	            RenderOptions.SetBitmapScalingMode(thumb, BitmapScalingMode.NearestNeighbor);
 98	            frameStrip.Children.Add(thumb);
 99	        }
100	        root.Children.Add(frameStrip);
101	
102	        // 操作按钮
103	        var buttons = new StackPanel
104	        {
105	            Orientation = Orientation.Horizontal,
106	            HorizontalAlignment = HorizontalAlignment.Right,
107	            Margin = new Thickness(0, 14, 0, 0),
108	        };
109	        var cancel = new Button { Content = "取消", Width = 80, Margin = new Thickness(0, 0, 8, 0), Padding = new Thickness(4) };
110	        cancel.Click += (_, _) => { DialogResult = false; };
111	        var confirm = new Button
112	        {
113	            Content = "导入此宠物",
114	            Width = 110,
115	            Padding = new Thickness(4),
116	            IsDefault = true,
117	            Style = (Style)Application.Current.FindResource("ButtonPrimaryStyle"),
118	        };
119	        confirm.Click += (_, _) => { DialogResult = true; };
120	        buttons.Children.Add(cancel);
121	        buttons.Children.Add(confirm);
122	        root.Children.Add(buttons);
123	
124	        Content = root;
125	        WpfLocalizer.ApplyNew(this, localization);
126	    }
