128	    /// <summary>导入时由 PetWindow 读取：原始文件字节 + 建议名。</summary>
129	    public (byte[] Bytes, string Name) ImportPayload => (_sourceBytes, _suggestedName);
130	
131	    /// <summary>解码源图位图（Bgra32）。SourceRgba 缺失时回退透明图（不崩）。</summary>
132	    private static BitmapSource BuildSourcePreview(SpriteSheet sheet)
133	    {
134	        if (sheet.SourceRgba is { Length: > 0 } rgba)
135	        {
136	            var pixels = RgbaToBgra(rgba);
137	            return BitmapSource.Create(
138	                sheet.SourceWidth, sheet.SourceHeight, 96, 96, PixelFormats.Bgra32, null,
139	                pixels, sheet.SourceWidth * 4);
140	        }
141	        return BitmapSource.Create(
142	            sheet.SourceWidth, sheet.SourceHeight, 96, 96, PixelFormats.Bgra32, null,
143	            new byte[sheet.SourceWidth * sheet.SourceHeight * 4], sheet.SourceWidth * 4);
144	    }
145	
146	    private static byte[] RgbaToBgra(byte[] rgba)
147	    {
148	        var bgra = new byte[rgba.Length];
149	        for (var i = 0; i < rgba.Length; i += 4)
150	        {
151	            bgra[i] = rgba[i + 2];
152	            bgra[i + 1] = rgba[i + 1];
153	            bgra[i + 2] = rgba[i];
154	            bgra[i + 3] = rgba[i + 3];
155	        }
156	        return bgra;
157	    }
158	
159	    private static BitmapSource FrameToBitmap(SpriteFrame frame)
160	        => BitmapSource.Create(
161	            frame.Width, frame.Height, 96, 96, PixelFormats.Bgra32, null,
162	            RgbaToBgra(frame.Rgba), frame.Width * 4);
163	}
