 809	    private UIElement BuildPetsPage()
 810	    {
 811	        var store = _store.LoadPetStore() ?? PetStoreModel.EmptyPetStore();
 812	        _previewCards.Clear();
 813	
 814	        var stack = new StackPanel();
 815	
 816	        // 页头：标题 + 添加按钮
 817	        var headerRow = new Grid { Margin = new Thickness(28, 22, 28, 14) };
 818	        headerRow.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
 819	        headerRow.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
 820	        var titleStack = new StackPanel();
 821	        titleStack.Children.Add(new TextBlock
 822	        {
 823	            Text = "我的宠物",
 824	            FontSize = 20,
 825	            FontWeight = FontWeights.SemiBold,
 826	            Foreground = Brush("TextPrimaryBrush"),
 827	        });
 828	        titleStack.Children.Add(new TextBlock
 829	        {
 830	            Text = "管理桌面上的小伙伴",
 831	            FontSize = 12,
 832	            Foreground = Brush("TextTertiaryBrush"),
 833	            Margin = new Thickness(0, 3, 0, 0),
 834	        });
 835	        Grid.SetColumn(titleStack, 0);
 836	        headerRow.Children.Add(titleStack);
 837	
 838	        var add = new Button
 839	        {
 840	            Content = "添加宠物",
 841	            Style = AppStyle("ButtonPrimaryStyle"),
 842	            Height = 32,
 843	            Padding = new Thickness(16, 4, 16, 4),
 844	            VerticalAlignment = VerticalAlignment.Center,
 845	        };
 846	        add.Click += async (_, _) => await ImportPetAsync();
 847	        Grid.SetColumn(add, 1);
 848	        headerRow.Children.Add(add);
 849	
 850	        var scrollStack = new StackPanel();
 851	        scrollStack.Children.Add(headerRow);
 852	
 853	        var listStack = new StackPanel { Margin = new Thickness(28, 0, 28, 24) };
 854	        if (store.Instances.Count == 0)
 855	        {
 856	            listStack.Children.Add(Card(new TextBlock
 857	            {
 858	                Text = "还没有宠物。点击右上角「添加宠物」导入一张精灵图，或直接把 PNG/WebP 拖到桌面宠物上。",
 859	                FontSize = 13,
 860	                TextWrapping = TextWrapping.Wrap,
 861	                Foreground = Brush("TextSecondaryBrush"),
 862	            }));
 863	        }
 864	        foreach (var instance in store.Instances)
 865	        {
 866	            listStack.Children.Add(Card(BuildPetCard(instance), margin: 12));
 867	        }
 868	        scrollStack.Children.Add(listStack);
 869	
 870	        var scroll = new ScrollViewer
 871	        {
 872	            Content = scrollStack,
 873	            VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
 874	            HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled,
 875	        };
 876	        return scroll;
 877	    }
