 879	    private Grid BuildPetCard(PetInstance instance)
 880	    {
 881	        var grid = new Grid();
 882	        grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(96) });
 883	        grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
 884	
 885	        var preview = new PetPreviewCard(_spriteLoader, instance.SpriteSlug);
 886	        _previewCards.Add(preview);
 887	        var previewHost = new Border
 888	        {
 889	            Background = Brush("WindowBgBrush"),
 890	            BorderBrush = Brush("DividerBrush"),
 891	            BorderThickness = new Thickness(1),
 892	            CornerRadius = new CornerRadius(12),
 893	            Width = 96,
 894	            Height = 96,
 895	            Child = preview,
 896	        };
 897	        grid.Children.Add(previewHost);
 898	
 899	        var details = new Grid
 900	        {
 901	            Margin = new Thickness(18, 1, 0, 1),
 902	            VerticalAlignment = VerticalAlignment.Center,
 903	        };
 904	        details.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
 905	        details.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
 906	
 907	        var header = new Grid();
 908	        header.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
 909	        header.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
 910	        var identity = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center };
 911	        identity.Children.Add(new TextBlock
 912	        {
 913	            Text = instance.Name,
 914	            FontSize = 15,
 915	            FontWeight = FontWeights.SemiBold,
 916	            Foreground = Brush("TextPrimaryBrush"),
 917	            TextTrimming = TextTrimming.CharacterEllipsis,
 918	            MaxWidth = 180,
 919	            VerticalAlignment = VerticalAlignment.Center,
 920	        });
 921	        var care = _store.LoadCare().GetValueOrDefault(instance.Id);
 922	        var level = CareEngine.DisplayLevel(care?.Xp ?? 0);
 923	        var stage = CareEngine.StageName(CareEngine.LevelForXp(care?.Xp ?? 0));
 924	        identity.Children.Add(new Border
 925	        {
 926	            Background = Brush("SuccessSoftBrush"),
 927	            CornerRadius = new CornerRadius(7),
 928	            Padding = new Thickness(7, 2, 7, 2),
 929	            Margin = new Thickness(8, 0, 0, 0),
 930	            Child = new TextBlock
 931	            {
 932	                Text = $"{stage} · Lv {level}",
 933	                FontSize = 10.5,
 934	                Foreground = Brush("SuccessBrush"),
 935	                FontWeight = FontWeights.SemiBold,
 936	            },
 937	        });
 938	        header.Children.Add(identity);
 939	
 940	        var remove = new Button
 941	        {
 942	            Content = new System.Windows.Shapes.Path
 943	            {
 944	                Data = Geometry.Parse("M 4,5 L 12,5 M 6,5 L 6,3 L 10,3 L 10,5 M 5,6 L 6,14 L 10,14 L 11,6"),
 945	                Width = 16,
 946	                Height = 16,
 947	                Stretch = Stretch.Uniform,
 948	                Stroke = Brush("DangerBrush"),
 949	                StrokeThickness = 1.5,
 950	                StrokeStartLineCap = PenLineCap.Round,
 951	                StrokeEndLineCap = PenLineCap.Round,
 952	                StrokeLineJoin = PenLineJoin.Round,
 953	            },
 954	            Style = AppStyle("ButtonIconStyle"),
 955	            Foreground = Brush("DangerBrush"),
 956	            Width = 30,
