 250	    public async Task SendChatAsync(string text, bool withScreenContext)
 251	    {
 252	        using var runtimeLease = _runtime.Acquire();
 253	        var pipeline = runtimeLease?.Value.Pipeline;
 254	        if (pipeline is null)
 255	        {
 256	            OnUiThread(() => _chatWindow.AppendAssistantAsync(
 257	                _i18n.T("（未配置模型连接，请到设置 → AI 助手 → 模型连接）")));
 258	            return;
 259	        }
