 261	        DesktopPet.Core.Ai.PipelineResult result;
 262	        try
 263	        {
 264	            await _chatSerial.WaitAsync();
 265	            try
 266	            {
 267	                // Phase 6：记忆注入（开关开 + 有画像）+ 亲密度语气指令（开关开）
 268	                Func<string>? memoryInjector = _settings.Ai.MemoryEnabled
 269	                    ? () => MemoryProfileExtractor.Inject(_profile)
 270	                    : null;
 271	                Func<string>? suffixFactory = _settings.Ai.IntimacyEnabled
 272	                    ? () => _intimacy.BuildIntimacyDirective()
 273	                    : null;
 274	                result = await pipeline.RunAsync(text, _conversation.BuildContext(CurrentContextTokens()), withScreenContext,
 275	                    memoryInjector: memoryInjector,
 276	                    systemPromptSuffix: suffixFactory,
 277	                    maxTokens: CurrentMaxOutputTokens(),
 278	                    ct: runtimeLease!.Value.LifetimeToken);
 279	                if (result.Ok)
 280	                {
 281	                    // L1 会话窗口维护：成功后追加本轮（预算裁剪与 L2 摘要由 ConversationMemory 负责）
 282	                    _conversation.Append(text, result.Text!);
 283	                    if (result.TokensUsed > 0) RecordTokens(result.TokensUsed);
 284	                    RecordChatSuccess(text, result.TokensUsed);   // 亲密度 + 画像更新
 285	                }
 286	            }
 287	            finally
 288	            {
 289	                _chatSerial.Release();
 290	            }
 291	        }
 292	        catch (ProviderException ex)
 293	        {
 294	            OnUiThread(() => _chatWindow.AppendAssistantAsync(ex.Code switch
 295	            {
 296	                "auth" => _i18n.T("（API Key 无效，请检查模型连接）"),
 297	                "timeout" => _i18n.T("（模型响应超时了，让我歇口气~）"),
 298	                _ => _i18n.T("（模型连接出错了）"),
 299	            }));
 300	            return;
 301	        }
 302	        catch (Exception)
 303	        {
 304	            OnUiThread(() => _chatWindow.AppendAssistantAsync(_i18n.T("（出错了，请稍后再试）")));
 305	            return;
 306	        }
 307	
 308	        // UI 输出在串行段外（不延长锁持有；Speech 等同样移出）
 309	        if (!result.Ok)
 310	        {
 311	            OnUiThread(() => _chatWindow.AppendAssistantAsync(result.Error switch
 312	            {
 313	                "empty" => _i18n.T("（消息不能为空）"),
 314	                "too-long" => _i18n.T("（消息太长了）"),
 315	                _ => _i18n.T("（出错了）"),
 316	            }));
 317	            return;
 318	        }
 319	        OnUiThread(() => _chatWindow.AppendAssistantAsync(result.Text!));
 320	        Speak(result.Text!);                          // 语音开关 + 对话模式
 321	    }
