 20	/// 输出模式服务：三模式切换（创建/销毁弹幕窗；AI 输出路由到弹幕/对话/丢弃）。
 21	/// 模式切换 <300ms 且关闭后无窗口残留（窗口实例即建即毁）。
 22	/// </summary>
 23	public sealed class ModeService
 24	{
 25	    private readonly Func<Windows.DanmakuWindow> _danmakuFactory;
 26	    private readonly Action<AiOutput> _routeToChat;
 27	    private readonly Action<string> _routeToBubble;
 28	    private readonly Func<bool> _isFullscreen;
 29	
 30	    private Windows.DanmakuWindow? _danmakuWindow;
 31	    private OutputMode _mode = OutputMode.Silent;
 32	    private bool _fullscreenSuppressed;
 33	
 34	    public OutputMode Mode => _mode;
 35	
 36	    public event Action<OutputMode>? ModeChanged;
 37	
 38	    public ModeService(
 39	        Func<Windows.DanmakuWindow> danmakuFactory,
 40	        Action<AiOutput> routeToChat,
 41	        Action<string> routeToBubble,
 42	        Func<bool>? isFullscreen = null)
 43	    {
 44	        _danmakuFactory = danmakuFactory;
 45	        _routeToChat = routeToChat;
 46	        _routeToBubble = routeToBubble;
 47	        _isFullscreen = isFullscreen ?? (() => false);
 48	    }
 49	
 50	    /// <summary>切换模式：立即生效（旧窗口关闭即销毁，新窗口按需创建）。</summary>
 51	    public void SetMode(OutputMode mode)
 52	    {
 53	        if (_mode == mode) return;
 54	        _mode = mode;
 55	        if (_fullscreenSuppressed) CloseDanmakuWindow();
 56	        else if (_mode != OutputMode.Danmaku) CloseDanmakuWindow();
 57	        ModeChanged?.Invoke(mode);
 58	    }
 59	
 60	    public bool FullscreenSuppressed => _fullscreenSuppressed;
 61	
 62	    public void SetFullscreenSuppressed(bool suppressed)
 63	    {
 64	        if (_fullscreenSuppressed == suppressed) return;
 65	        _fullscreenSuppressed = suppressed;
 66	        if (suppressed) CloseDanmakuWindow();
 67	    }
 68	
 69	    /// <summary>路由 AI 输出（按当前模式；静默或全屏时丢弃主动输出）。</summary>
 70	    public void RouteOutput(AiOutput output)
 71	    {
 72	        if (FullscreenOutputPolicy.ShouldSuppress(
 73	                output.FromAnalysis,
 74	                _fullscreenSuppressed,
 75	                output.FromAnalysis && _isFullscreen())) return;
 76	
 77	        switch (_mode)
 78	        {
 79	            case OutputMode.Danmaku:
 80	                if (_danmakuWindow is null || !_danmakuWindow.IsVisible)
 81	                {
 82	                    _danmakuWindow = _danmakuFactory();
 83	                    _danmakuWindow.Show();
 84	                }
 85	                _danmakuWindow.ShowDanmaku(output.Text);
 86	                break;
 87	            case OutputMode.Chat:
 88	                _routeToChat(output); // ChatWindow 按需出现（EnsureVisible 由 App 接线）
 89	                break;
 90	            case OutputMode.Bubble:
 91	                _routeToBubble(output.Text); // 宠物头上气泡（全员），不打断工作
 92	                break;
 93	            case OutputMode.Silent:
 94	                break; // 静默：无主动输出
 95	        }
 96	    }
 97	
 98	    public void Shutdown()
 99	    {
100	        CloseDanmakuWindow();
101	    }
102	
103	    private void CloseDanmakuWindow()
104	    {
105	        if (_danmakuWindow is not null)
106	        {
107	            _danmakuWindow.Close(); // Close 即销毁（模式切换无残留）
108	            _danmakuWindow = null;
109	        }
110	    }
111	}
289	    /// <summary>注入 i18n，并初始化已创建窗口的静态文案。</summary>
290	    public void SetI18n(I18nService i18n)
291	    {
292	        _i18n = i18n;
293	        foreach (var window in _windows.Values) window.ApplyLocalization(i18n);
294	    }
295	
296	    public void ApplyLocalization()
297	    {
298	        if (_i18n is null) return;
299	        foreach (var window in _windows.Values) window.ApplyLocalization(_i18n);
300	        _floatingBall?.ApplyLocalization(_i18n);
301	        _settingsWindow?.ApplyLocalization();
302	    }
303

